package pt.qpetiscos.agenda;
import android.content.*;import android.widget.*;import android.view.View;import org.json.*;import java.util.*;
public class WidgetRows extends RemoteViewsService {public RemoteViewsFactory onGetViewFactory(Intent i){return new Factory(getApplicationContext(),i.getIntExtra("wid",-1),i.getBooleanExtra("take",false));}static class Factory implements RemoteViewsFactory{final Context c;final int id;final boolean take;final ArrayList<JSONObject> rows=new ArrayList<>();Factory(Context c,int id,boolean take){this.c=c;this.id=id;this.take=take;}public void onCreate(){}public void onDestroy(){rows.clear();}public void onDataSetChanged(){rows.clear();try{JSONArray a=new JSONArray(c.getSharedPreferences("widget_rows",0).getString("rows"+id,"[]"));String date=WidgetAgenda.date(c,id).toString(),filter=WidgetAgenda.filter(c,id,take);for(int n=0;n<a.length();n++){JSONObject e=a.getJSONObject(n);if(date.equals(e.optString("event_date"))&&("all".equals(filter)||filter.equals(e.optString("type"))))rows.add(e);}}catch(Exception ignored){}}public int getCount(){return rows.size();}public RemoteViews getLoadingView(){return null;}public int getViewTypeCount(){return 1;}public long getItemId(int p){return rows.get(p).optString("id").hashCode();}public boolean hasStableIds(){return true;}Intent click(String op,JSONObject e){return new Intent().putExtra("op",op).putExtra("event",e.optString("id")).putExtra("done",!e.optBoolean("completed"));}public RemoteViews getViewAt(int p){if(p<0||p>=rows.size())return null;JSONObject e=rows.get(p);int t=WidgetAgenda.theme(c,id),fg=WidgetAgenda.fg(t);boolean res="reserva".equals(e.optString("type")),done=e.optBoolean("completed"),expanded=c.getSharedPreferences("widget_state",0).getBoolean("expanded"+id+e.optString("id"),false);RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.widget_row);v.setInt(R.id.row_root,"setBackgroundResource",(res?new int[]{R.drawable.widget_row_res0,R.drawable.widget_row_res1,R.drawable.widget_row_res2}:new int[]{R.drawable.widget_row_take0,R.drawable.widget_row_take1,R.drawable.widget_row_take2})[t]);for(int x:new int[]{R.id.row_name,R.id.row_time,R.id.row_notes,R.id.row_expand,R.id.row_done})v.setTextColor(x,fg);v.setInt(R.id.row_delete,"setColorFilter",fg);v.setTextColor(R.id.row_expand,new int[]{0xff966039,0xfff2c59a,0xffffe1ba}[t]);v.setTextViewText(R.id.row_name,e.optString("name"));v.setInt(R.id.row_name,"setPaintFlags",done?17:1);String time=e.optString("event_time");v.setTextViewText(R.id.row_time,time.substring(0,Math.min(5,time.length()))+" · "+(res?"Reserva":"Takeaway"));String notes=e.isNull("notes")?"":e.optString("notes");v.setTextViewText(R.id.row_notes,expanded?notes:notes.replace('\n',' '));v.setInt(R.id.row_notes,"setMaxLines",expanded?Integer.MAX_VALUE:1);android.os.Bundle opts=android.appwidget.AppWidgetManager.getInstance(c).getAppWidgetOptions(id);int width=opts.getInt(android.appwidget.AppWidgetManager.OPTION_APPWIDGET_MIN_WIDTH,250);android.util.DisplayMetrics dm=c.getResources().getDisplayMetrics();android.graphics.Paint paint=new android.graphics.Paint();paint.setTextSize(12*dm.scaledDensity);boolean canExpand=expanded||notes.contains("\n")||paint.measureText(notes)>Math.max(24,width-150)*dm.density;v.setTextViewText(R.id.row_expand,expanded?"Ver menos  ⌃":"Ver mais  ⌄");v.setContentDescription(R.id.row_expand,expanded?"Recolher notas":"Expandir notas");v.setViewVisibility(R.id.row_notes,notes.isEmpty()?View.GONE:View.VISIBLE);v.setViewVisibility(R.id.row_expand,!notes.isEmpty()&&canExpand?View.VISIBLE:View.GONE);v.setTextViewText(R.id.row_done,done?"✓":"○");v.setOnClickFillInIntent(R.id.row_root,click("view",e));v.setOnClickFillInIntent(R.id.row_expand,click("expand",e));v.setOnClickFillInIntent(R.id.row_done,click("toggle",e));v.setOnClickFillInIntent(R.id.row_delete,click("delete",e));return v;}}}
